            $k('How do I paste values from Excel into the form?', 'paste from excel, copy paste values, paste readings, paste excel cells, copy from excel', 'Paste one value per box (click the box, Ctrl + V). Whole-row paste into many boxes is not supported; loading the machine file avoids retyping.', [], $dtr),
            $k('Can I use the Tab key to move between boxes?', 'tab key move, tab between fields, keyboard navigation form, next box key, enter key next field', 'Yes. Tab moves to the next box and Shift + Tab goes back; in lookup boxes Tab also runs the lookup.', [], $dtr),
            $k('How do I enter a date in the date boxes?', 'enter date, date format, type date, date box format, date input', 'Use the format shown in the box (for example 2026-10-12 or with time). If the box has a calendar, pick the date from it.', [], $dtr),
            $k('How do I clear the form to start over?', 'clear form, reset form, start over, empty form, blank form', 'Press "+ New Record" to get an empty form, or reload the report from the Lab Tracker to discard unsaved changes.', [], $dtr),
            $k('Why is the Save button not reacting?', 'save button not reacting, save click nothing, save no response, save disabled, cannot press save', 'Check the message at the top: a missing Lab Reference No. stops the save. Reload with Ctrl + F5 and try again; if it still fails, tell an administrator what the message says.', [], $dtr),
            $k('I see HTTP 401 errors', 'http 401, 401 error, unauthorized error, 401 unauthorized, session lost error', '401 means you are no longer signed in (idle for 30 minutes or the session was lost). Sign in again.', [], ['error_match' => '401']),
            $k('I see HTTP 403 or 422 errors', 'http 403, http 422, 403 forbidden, 422 error, validation error server', '403 means your account may not do that (or the page token expired: reload with Ctrl + F5). 422 means something required was missing, such as a Lab Reference No. or an Application No.', [], ['error_match' => '403']),
            $k('I see HTTP 502 or 503 errors', 'http 502, http 503, bad gateway, service unavailable, 502 error, 503 error', 'The server or a service behind it is busy or down. Wait a minute and retry; if it stays, tell an administrator. In InterLink Sync it can also mean InterLink itself is unreachable.', [], ['error_match' => '50']),
            $k('InterLink is unreachable from the server', 'interlink unreachable, cannot reach interlink, interlink down, intertek not reachable, interlink offline', 'The Sync Center shows "InterLink could not be reached". Check that InterLink opens in your own browser; if it does not, it is down and sync waits. Otherwise tell an administrator to check the server\'s internet access.', [], $il + ['diagnose' => 'interlink_session']),
            $k('Why is the date on the PDF different from today?', 'pdf date different, date on pdf, issue date pdf, report date not today, printed date', 'The sheet shows the report\'s own dates (received, tested, finished), not today\'s date. The browser may add the print date in its header if "Headers and footers" is on.', [], $dtr),
            $k('How do I zoom the report preview?', 'zoom preview, bigger preview, enlarge report preview, zoom in report', 'Use Ctrl + mouse wheel or Ctrl and + in the browser, or open the PDF and zoom there.', [], $dtr),
            $k('Can I open the report on my phone?', 'report on phone, phone view report, mobile report preview, view pdf phone', 'Yes. Download the PDF from the preview on your phone, or open the page and scroll; data entry is easier on a computer.', [], $dtr),
            $k('How do I share a report with the customer?', 'share with customer, send to buyer, give report customer, customer copy, external share', 'Send the PDF you downloaded from the preview, following your lab\'s release rules. NEXUS-L has no external sharing links.', [], $dtr),
            $k('How do I get a copy of the machine file?', 'copy machine file, get excel file, download machine file, machine file copy, original excel', 'The original file stays on the machine PC or share. Ask the person responsible for the machine; NEXUS-L only reads a copy and cannot download it for you.', [], $dtr),
            $k('How do I report a wrong standard value?', 'report wrong standard, standard error report, wrong spec value, standard incorrect tell', 'Press "Talk to an administrator" with the material type, the value shown and the value you expected; standards are corrected in the master data.', [], $dtr),
            $k('What should I do if InterLink changes its form?', 'interlink form changed, new interlink layout, interlink update changed fields, fields moved interlink, interlink redesign', 'Tell an administrator. The box names used by the fill are kept in NEXUS-L and can be updated; until then some boxes may show as "not found" when you fill.', [], $il),
            $k('Why do some report numbers have extra letters?', 'extra letters report number, report no letters, suffix report, r01 suffix, lab ref suffix meaning', 'Suffixes mark the version or side: -L / -R for left and right shoes, and a retest report number may end in -R01. Always use the exact number printed on the report.', [], $dtr),
            $k('How do I thank or give feedback on the assistant?', 'give feedback assistant, thumbs up, rate answer, helpful button, feedback bot', 'Press "Helpful" or "Not helpful" under an answer. Not-helpful answers are reviewed by the administrators so the assistant improves.'),
            $k('How do I get the latest instructions after an update?', 'latest instructions, new features after update, what changed, release notes, whats new', 'Reload with Ctrl + F5, then ask the assistant or open the Help page. Administrators tell users about big changes.', [], ['actions' => [$o('Open Help', 'help')]]),
            $k('Can I use two tabs at once?', 'two tabs, multiple tabs, several browser tabs, open two reports, tabs at same time', 'Yes, but save each report before switching so you do not overwrite one with the other, and do not open the same report in two tabs.'),
